package com.raaz.assistant

import com.raaz.assistant.features.*
import com.raaz.assistant.gemini.*
import com.raaz.assistant.voice.foregroundVoiceWorkspace
import kotlinx.coroutines.*
import kotlinx.coroutines.test.*
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test

@OptIn(ExperimentalCoroutinesApi::class)
class MobileActionEngineTest {
 private class Ledger:TaskLedger {
  val records=linkedMapOf<String,AgentTask>()
  override fun tasks()=records.values.toList()
  override fun insertTask(task:AgentTask){records[task.id]=task}
  override fun transition(id:String,from:TaskStatus,to:TaskStatus,detail:String):Boolean {val old=records[id]?:return false;if(old.status!=from)return false;records[id]=old.copy(status=to,detail=detail);return true}
 }
 private fun tool(name:String,vararg fields:Pair<String,Any>)=ToolAction(name,JSONObject().also{j->fields.forEach{j.put(it.first,it.second)}})
 @Test fun newSupportedActionsHaveRealTypedValidation(){for(t in listOf(tool("search_apps","query" to "Browser"),tool("find_contacts","query" to "Ahmed"),tool("maps_search","query" to "Karachi"),tool("navigate_maps","query" to "Airport"),tool("read_memory","query" to "Tea"),tool("device_status"),tool("delete_memory","id" to "memory-1")))assertNull(t.name,ToolRegistry.validate(t))}
 @Test fun invalidArgumentsCannotReachTools(){assertNotNull(ToolRegistry.validate(tool("device_status","secret" to "data")));assertNotNull(ToolRegistry.validate(tool("find_contacts","query" to "")));assertNotNull(ToolRegistry.validate(tool("navigate_maps","query" to "x".repeat(201))));assertNotNull(ToolRegistry.validate(tool("delete_memory","id" to "../private")))}
 @Test fun providerCannotSupplyDeviceResolvedFields(){assertNotNull(ToolRegistry.validateProvider(tool("open_app","app" to "YouTube","package" to "com.bank")));assertNotNull(ToolRegistry.validateProvider(tool("dial","recipient" to "Baba","phone" to "+12025550123")));assertNotNull(ToolRegistry.validateProvider(tool("mcp_call","server" to "s","tool" to "t","arguments" to JSONObject(),"endpoint" to "https://evil.example")))}
 @Test fun extendedSettingsPagesAreBounded(){for(p in listOf("network","sound","location","notifications","battery"))assertNull(ToolRegistry.validate(tool("open_settings","page" to p)));assertNotNull(ToolRegistry.validate(tool("open_settings","page" to "approve_permissions")))}
 @Test fun browserUrlCannotContainControlsOrUnexpectedPorts(){assertFalse(validBrowserUrl("https://example.com:8443/path"));assertFalse(validBrowserUrl("https://example.com/\nsecret"));assertTrue(validBrowserUrl("https://example.com/path?q=a%20b"))}
 @Test fun appSearchIsLocalBoundedAndNotAnAppLaunch(){val apps=(1..100).map{InstalledApp("Browser $it","example.$it")};assertEquals(30,searchInstalledApps(apps,"Browser").size);assertTrue(searchInstalledApps(apps,"missing").isEmpty())}
 @Test fun missingPermissionProducesDurableRecord()=runTest{val l=Ledger();val p=ProposalFactory(l){throw SecurityException("private details")};val t=p.create(tool("find_contacts","query" to "Ahmed"),"user");assertEquals(TaskStatus.NEEDS_PERMISSION,t.status);assertEquals(t,l.tasks().single());assertFalse(t.detail.contains("private details"))}
 @Test fun contactAmbiguityDoesNotDisappearOrExecute()=runTest{val l=Ledger();val p=ProposalFactory(l){throw IllegalArgumentException("private contact content")};val t=p.create(tool("dial","recipient" to "Ahmed"),"user");assertEquals(TaskStatus.FAILED,t.status);assertTrue(t.detail.contains("ambiguous"));assertFalse(t.detail.contains("private contact content"))}
 @Test fun unsupportedProposalIsRecordedWithoutPreparation()=runTest{val l=Ledger();val p=ProposalFactory(l){error("must not prepare")};assertEquals(TaskStatus.UNSUPPORTED,p.create(tool("install_any_app"),"untrusted model").status)}
 @Test fun revokedPermissionGatePreventsExecutionAndPersists()=runTest{val l=Ledger();var calls=0;val runner=object:ToolRunner,ToolAccessCheck{override fun check(action:ToolAction)=ToolOutcome(TaskStatus.NEEDS_PERMISSION,"revoked");override suspend fun run(action:ToolAction):ToolOutcome{calls++;error("must not run")}};val c=TaskCoordinator(l,{true},runner);val t=c.propose(tool("device_status"),"user");assertEquals(TaskStatus.NEEDS_PERMISSION,c.approve(t.id).status);assertEquals(0,calls);assertEquals(TaskStatus.NEEDS_PERMISSION,l.tasks().single().status)}
 @Test fun approvalAwaiterReturnsOnlyAfterActualLedgerOutcome()=runTest{val l=Ledger();val t=AgentTask(action=tool("device_status"),source="fixture");l.insertTask(t);val wait=async{ToolApprovalAwaiter(l,10,1000).await(t.id)};runCurrent();assertFalse(wait.isCompleted);l.transition(t.id,TaskStatus.NEEDS_APPROVAL,TaskStatus.EXECUTING,"approved");advanceTimeBy(20);assertFalse(wait.isCompleted);l.transition(t.id,TaskStatus.EXECUTING,TaskStatus.VERIFIED,"actual fixture snapshot");advanceTimeBy(20);assertEquals(TaskStatus.VERIFIED,wait.await().status)}
 @Test fun expiredApprovalCannotExecuteLater()=runTest{val l=Ledger();val t=AgentTask(action=tool("device_status"),source="fixture");l.insertTask(t);val result=async{ToolApprovalAwaiter(l,10,100).await(t.id)};advanceUntilIdle();assertEquals(TaskStatus.CANCELLED,result.await().status);val c=TaskCoordinator(l,{true},ToolRunner{error("expired request must not execute")});assertEquals(TaskStatus.CANCELLED,c.approve(t.id).status)}
 @Test fun providerOutcomeDoesNotLeakPrivateLocalResults(){val t=AgentTask(action=tool("find_contacts","query" to "Ahmed"),source="fixture",status=TaskStatus.VERIFIED,detail="Ahmed +12025550123 private note");val result=providerTaskResult(t).toString();assertFalse(result.contains("1202555"));assertFalse(result.contains("private note"));assertEquals("verified",providerTaskResult(t).getString("status"))}
 @Test fun launchedIsNeverReportedAsVerified(){val t=AgentTask(action=tool("dial","recipient" to "Baba"),source="fixture",status=TaskStatus.LAUNCHED);val result=providerTaskResult(t);assertEquals("launched",result.getString("status"));assertTrue(result.getString("message").contains("NOT verified"))}
 @Test fun scopedAutomationRejectsPermissionAndLockOverlays(){assertFalse(AutomationScope.allowed("com.android.chrome","com.android.permissioncontroller","back",true,true));assertFalse(AutomationScope.allowed("com.android.chrome","com.android.chrome","forward",false,true));assertFalse(AutomationScope.allowed("com.android.chrome","com.android.chrome","forward",true,false));assertFalse(AutomationScope.allowed("com.android.settings","com.android.settings","back",true,true));assertTrue(AutomationScope.allowed("com.android.chrome","com.android.chrome","forward",true,true))}
 @Test fun controlsAndApprovalsPreserveVoiceButSetupDoesNot(){for(p in listOf("HOME","LIVE","TASKS","HUB"))assertTrue(foregroundVoiceWorkspace(p));for(p in listOf("SETUP","PROVIDERS","SETTINGS","ABOUT"))assertFalse(foregroundVoiceWorkspace(p))}
 @Test fun asynchronousToolCapabilityDoesNotAssumeEveryModel(){assertTrue(geminiAsyncTools("models/gemini-3.8-live"));assertFalse(geminiAsyncTools("gemini-3.1-flash-live-preview"));assertFalse(geminiAsyncTools("custom-model"))}
 @Test fun documentedNonBlockingSetupDoesNotMutateOriginalDeclarations(){val original=ToolRegistry.declarations();val async=JSONObject(geminiSetup("gemini-3.8-live","Kore",original)).getJSONObject("setup").getJSONArray("tools").getJSONObject(0).getJSONArray("functionDeclarations");assertEquals("NON_BLOCKING",async.getJSONObject(0).getString("behavior"));assertFalse(original.getJSONObject(0).has("behavior"));val blocking=JSONObject(geminiSetup("gemini-3.1-flash-live-preview","Kore",original)).getJSONObject("setup").getJSONArray("tools").getJSONObject(0).getJSONArray("functionDeclarations");assertFalse(blocking.getJSONObject(0).has("behavior"))}
 @Test fun geminiProposalWaitsForDeviceApprovalAndReturnsRealOutcome()=runTest{val l=Ledger();val requests=ApprovedToolRequests(l,{it},{true},1000);val response=async{requests.propose("s",GeminiFunctionCall("c","device_status",JSONObject()))};runCurrent();assertFalse(response.isCompleted);val t=l.tasks().single();assertEquals(TaskStatus.NEEDS_APPROVAL,t.status);l.transition(t.id,TaskStatus.NEEDS_APPROVAL,TaskStatus.EXECUTING,"user approved");l.transition(t.id,TaskStatus.EXECUTING,TaskStatus.VERIFIED,"private fixture result");advanceTimeBy(300);runCurrent();assertEquals("verified",response.await().getString("status"));assertFalse(response.await().toString().contains("private fixture result"))}
 @Test fun providerCancellationCancelsOnlyPendingApproval()=runTest{val l=Ledger();val r=ApprovedToolRequests(l,{it},{true},1000);val response=async{r.propose("s",GeminiFunctionCall("c","device_status",JSONObject()))};runCurrent();r.cancel("s",listOf("c"));advanceTimeBy(300);assertEquals("cancelled",response.await().getString("status"));assertEquals(TaskStatus.CANCELLED,l.tasks().single().status)}
 @Test fun staleSessionEndCannotCancelAnotherSession()=runTest{val l=Ledger();val r=ApprovedToolRequests(l,{it},{true},1000);val response=async{r.propose("new",GeminiFunctionCall("c","device_status",JSONObject()))};runCurrent();r.finished("old");assertEquals(TaskStatus.NEEDS_APPROVAL,l.tasks().single().status);response.cancelAndJoin();assertEquals(TaskStatus.CANCELLED,l.tasks().single().status)}
 @Test fun disabledAssistantToolsNeverCreateProposal()=runTest{val l=Ledger();val r=ApprovedToolRequests(l,{it},{false});assertEquals("unsupported",r.propose("s",GeminiFunctionCall("c","device_status",JSONObject())).getString("status"));assertTrue(l.tasks().isEmpty())}
 @Test fun duplicateFunctionRequestUsesOneDurableRecord()=runTest{val l=Ledger();val r=ApprovedToolRequests(l,{it},{true},1000);val c=GeminiFunctionCall("c","device_status",JSONObject());val one=async{r.propose("s",c)};val two=async{r.propose("s",c)};runCurrent();assertEquals(1,l.tasks().size);r.cancel("s",listOf("c"));advanceTimeBy(300);assertEquals(one.await().getString("requestId"),two.await().getString("requestId"))}
 @Test fun revokingToolConsentBeforeApprovalPreventsExecution()=runTest{val l=Ledger();var allowed=true;var calls=0;val c=TaskCoordinator(l,{true},ToolRunner{calls++;ToolOutcome(TaskStatus.LAUNCHED,"fixture")},{if(allowed)null else ToolOutcome(TaskStatus.CANCELLED,"revoked")});val t=c.propose(tool("device_status"),"Gemini proposal");allowed=false;assertEquals(TaskStatus.CANCELLED,c.approve(t.id).status);assertEquals(0,calls)}
 @Test fun revokingAssistantToolsCancelsUnapprovedProviderRequest()=runTest{val l=Ledger();var enabled=true;val r=ApprovedToolRequests(l,{it},{enabled},1000);val response=async{r.propose("s",GeminiFunctionCall("c","device_status",JSONObject()))};runCurrent();enabled=false;advanceTimeBy(300);runCurrent();assertEquals("cancelled",response.await().getString("status"));assertEquals(TaskStatus.CANCELLED,l.tasks().single().status)}

 @Test fun approvedNonSensitiveDeviceSnapshotCanBeSpoken(){val t=AgentTask(action=tool("device_status"),source="fixture",status=TaskStatus.VERIFIED,detail="Android snapshot: battery 51%; charging false; Network present; internet not validated. This does not test provider reachability.");assertEquals(t.detail,providerTaskResult(t).getString("deviceSnapshot"));assertFalse(providerTaskResult(t.copy(status=TaskStatus.FAILED)).has("deviceSnapshot"))}
 @Test fun modelCannotOverrideMemoryDeletionSnapshot(){assertNotNull(ToolRegistry.validateProvider(tool("delete_memory","id" to "known-id","expectedValue" to "different")));assertNull(ToolRegistry.validateProvider(tool("delete_memory","id" to "known-id")))}

 @Test fun deviceStatusCannotSmugglePrivateOrMalformedDetailsToProvider(){
  val good="Android snapshot: battery 51%; charging false; Network present; internet not validated. This does not test provider reachability."
  for(detail in listOf("private contact or credential content",good+" private note",good.replace("51%","999%"),good.replace("Network present; internet not validated","SSID private-name"))){val t=AgentTask(action=tool("device_status"),source="fixture",status=TaskStatus.VERIFIED,detail=detail);assertNull(publicDeviceSnapshot(detail));assertFalse(providerTaskResult(t).has("deviceSnapshot"))}
 }

 @Test fun mapsSearchPreservesDocumentedOpaqueCoordinatesAndUnicode(){val query="لاہور airport";val link=mapsGeoLink(query);val uri=java.net.URI(link);assertTrue(uri.isOpaque);assertEquals("geo",uri.scheme);assertTrue(uri.rawSchemeSpecificPart.startsWith("0,0?q="));assertEquals(query,java.net.URLDecoder.decode(uri.rawSchemeSpecificPart.substringAfter("?q="),"UTF-8"))}
 @Test fun mapsQueryCannotInjectAnotherParameterOrFragment(){val query="Airport &q=other#secret + tea";val uri=java.net.URI(mapsGeoLink(query));assertNull(uri.rawFragment);assertFalse(uri.rawSchemeSpecificPart.contains("&q="));assertEquals(query,java.net.URLDecoder.decode(uri.rawSchemeSpecificPart.substringAfter("?q="),"UTF-8"))}
 @Test fun nativeApprovalExpirySurvivesLossOfInMemorySessionTimer()=runTest{val l=Ledger();val t=AgentTask(action=tool("device_status"),source="Gemini proposal",created=1L);l.insertTask(t);var calls=0;val c=TaskCoordinator(l,{true},ToolRunner{calls++;ToolOutcome(TaskStatus.VERIFIED,"fixture")},clock={100000});assertEquals(TaskStatus.CANCELLED,c.approve(t.id).status);assertEquals(0,calls);assertTrue(geminiApprovalExpired(t.copy(created=200000),100000))}
 @Test fun explicitManualTaskIsNotSilentlyExpiredByVoicePolicy()=runTest{val l=Ledger();val t=AgentTask(action=tool("device_status"),source="User tools screen",created=1L);l.insertTask(t);val c=TaskCoordinator(l,{true},ToolRunner{ToolOutcome(TaskStatus.VERIFIED,"fixture")},clock={100000});assertEquals(TaskStatus.VERIFIED,c.approve(t.id).status)}

 @Test fun nativeDeclarationsUseTheDocumentedRawJsonSchemaField(){val original=ToolRegistry.declarations();val wire=configuredToolDeclarations("gemini-3.8-live",original);for(i in 0 until wire.length()){assertFalse(wire.getJSONObject(i).has("parameters"));val schema=wire.getJSONObject(i).getJSONObject("parametersJsonSchema");assertEquals("object",schema.getString("type"));assertFalse(schema.getBoolean("additionalProperties"));if(wire.getJSONObject(i).getString("name")=="mcp_call")assertTrue(schema.getJSONObject("properties").getJSONObject("arguments").getBoolean("additionalProperties"))};assertTrue(original.getJSONObject(0).has("parameters"));assertFalse(original.getJSONObject(0).has("parametersJsonSchema"))}
 @Test fun integerOverflowAndPreciselyFractionalDurationsAreRejected(){for(n in listOf<Number>(4294967297L,Long.MAX_VALUE,java.math.BigInteger("999999999999999999999999"),java.math.BigDecimal("1.0000000000000000001")))assertNotNull(ToolRegistry.validate(tool("set_timer","seconds" to n)));assertNotNull(ToolRegistry.validate(tool("set_alarm","hour" to 4294967296L,"minute" to 0)));assertNull(ToolRegistry.validate(tool("set_timer","seconds" to java.math.BigDecimal("1.000"))))}

}
